    'auth_faq_q1': 'मैं नई यात्रा कैसे बनाऊं?',
    'auth_faq_a1':
        'यात्रा टैब पर जाएं और "+" बटन पर टैप करें, या होम डैशबोर्ड के त्वरित कार्यों से "नई यात्रा" का उपयोग करें। अपना गंतव्य, तारीखें और रुचियां भरें, फिर AI योजनाकार को अपना यात्रा कार्यक्रम बनाने दें।',
    'auth_faq_q2':
