    'auth_faq_a2':
        'हां — अपनी यात्रा खोलें, यात्रा विवरण अपडेट करने के लिए संपादन आइकन पर टैप करें, या दिन-प्रतिदिन पड़ावों को जोड़ने, हटाने या पुनः क्रमबद्ध करने के लिए टूल ग्रिड से "शेड्यूल संपादित करें" का उपयोग करें।',
    'auth_faq_q3': 'बजट ट्रैकर कैसे काम करता है?',
    'auth_faq_a3':
        'बजट प्लानर में कुल बजट सेट करें, फिर प्रत्येक श्रेणी के तहत खर्च दर्ज करें। खर्च विभाजन आपके यात्रा समूह के बीच लागत को विभाजित करता है और ट्रैक करता है कि यात्रा आयोजक का कौन कितना बकाया है।',
    'auth_faq_q4': 'क्या ऐप ऑफ़लाइन काम करता है?',
    'auth_faq_a4':
        'मुख्य योजना सुविधाएं बिना कनेक्शन के काम करती हैं, लेकिन मौसम और बस प्रस्थान जैसे लाइव डेटा को रिफ्रेश करने के लिए इंटरनेट कनेक्शन की आवश्यकता होती है।',
    'auth_faq_q5': 'मैं दोस्तों को यात्रा में कैसे आमंत्रित करूं?',
    'auth_faq_a5':
