    'auth_expenses_logged_suffix': 'செலவுகள் பதிவு செய்யப்பட்டன',
    'auth_progress_group_2plus': '2+ குழுவில் பயணிக்கவும்',
    'auth_of_word': 'இல்',
    'auth_badges_earned_suffix': 'பேட்ஜ்கள் பெறப்பட்டன',
    'auth_version_prefix': 'பதிப்பு',
    'auth_about_description':
        'TravelPlanner உங்கள் பயணத்தை முழுமையாகத் திட்டமிட உதவுகிறது — பயணத் திட்டங்கள், வானிலை, போக்குவரத்து, பட்ஜெட் மற்றும் குழு ஒருங்கிணைப்பு, அனைத்தும் ஒரே இடத்தில்.',
    'auth_terms_of_service': 'சேவை விதிமுறைகள்',
    'auth_privacy_policy': 'தனியுரிமைக் கொள்கை',
    'auth_not_available_demo': 'இந்த டெமோவில் கிடைக்கவில்லை',
    'auth_made_with_flutter': 'Flutter உடன் உருவாக்கப்பட்டது 💙',
    'auth_help_center_subtitle': 'பொதுவான கேள்விகளுக்கான பதில்கள்',
    'auth_search_topic_hint': 'தலைப்பைத் தேடுங்கள்…',
    'auth_faq_title': 'அடிக்கடி கேட்கப்படும் கேள்விகள்',
    'auth_faq_q1': 'புதிய பயணத்தை எவ்வாறு உருவாக்குவது?',
    'auth_faq_a1':
        'பயணங்கள் தாவலுக்குச் சென்று "+" பொத்தானைத் தட்டவும், அல்லது முகப்புப் பலகையின் விரைவு செயல்களிலிருந்து "புதிய பயணம்" ஐப் பயன்படுத்தவும். உங்கள் இலக்கு, தேதிகள் மற்றும் ஆர்வங்களை நிரப்பவும், பின்னர் AI திட்டமிடுபவர் உங்கள் பயணத் திட்டத்தை உருவாக்கட்டும்.',
    'auth_faq_q2':
        'உருவாக்கப்பட்ட பிறகு எனது பயணத் திட்டத்தைத் திருத்த முடியுமா?',
    'auth_faq_a2':
        'ஆம் — உங்கள் பயணத்தைத் திறந்து, பயண விவரங்களைப் புதுப்பிக்க திருத்தும் ஐகானைத் தட்டவும், அல்லது ஒவ்வொரு நாளும் நிறுத்தங்களைச் சேர்க்க, அகற்ற அல்லது மறுவரிசைப்படுத்த கருவி கட்டத்திலிருந்து "அட்டவணையைத் திருத்து" ஐப் பயன்படுத்தவும்.',
    'auth_faq_q3': 'பட்ஜெட் டிராக்கர் எவ்வாறு செயல்படுகிறது?',
    'auth_faq_a3':
        'பட்ஜெட் திட்டமிடுபவரில் மொத்த பட்ஜெட்டை அமைக்கவும், பின்னர் ஒவ்வொரு வகையின் கீழும் செலவுகளைப் பதிவு செய்யவும். செலவுகளைப் பிரித்தல் உங்கள் பயணக் குழுவிற்கிடையே செலவுகளைப் பிரித்து, பயண ஏற்பாட்டாளருக்கு யார் கடன்பட்டிருக்கிறார்கள் என்பதைக் கண்காணிக்கிறது.',
    'auth_faq_q4': 'ஆப் ஆஃப்லைனில் வேலை செய்யுமா?',
    'auth_faq_a4':
        'முக்கிய திட்டமிடல் அம்சங்கள் இணைப்பு இல்லாமல் வேலை செய்யும், ஆனால் வானிலை மற்றும் பேருந்து புறப்பாடு போன்ற நேரடி தரவு புதுப்பிக்க இணைய இணைப்பு தேவை.',
    'auth_faq_q5': 'நண்பர்களை பயணத்திற்கு எவ்வாறு அழைப்பது?',
    'auth_faq_a5':
        'குழு பயணத்திலிருந்து, சேரும் குறியீட்டை உருவாக்க "உறுப்பினரை அழைக்கவும்" என்பதைத் தட்டவும், அல்லது நேரடியாகப் பகிரவும். நண்பர்கள் முகப்புப் பலகையில் "பயணத்தில் சேர" இலிருந்து குறியீட்டை உள்ளிடுகிறார்கள்.',
    'auth_no_matching_questions':
        'பொருந்தும் கேள்விகள் இல்லை — கீழே உள்ள ஆதரவைத் தொடர்பு கொள்ளவும்.',
    'auth_still_need_help': 'இன்னும் உதவி தேவையா?',
    'auth_support_reply_time':
        'எங்கள் ஆதரவு குழு பொதுவாக ஒரு நாளுக்குள் பதிலளிக்கும்.',
    'auth_contact_support': 'ஆதரவைத் தொடர்பு கொள்ளவும்',
    'auth_your_requests': 'உங்கள் கோரிக்கைகள்',
    'auth_havent_contacted_support':
