    'auth_privacy_security_subtitle':
        'நீங்கள் பகிர்வதையும் யாருடன் பகிர்வதையும் கட்டுப்படுத்துங்கள்',
    'auth_visibility_section': 'தெரியும் தன்மை',
    'auth_public_profile': 'பொது சுயவிவரம்',
    'auth_public_profile_on_desc':
        'யாரும் உங்கள் முழு சுயவிவர விவரங்களைப் பார்க்கலாம்',
    'auth_public_profile_off_desc':
        'தனிப்பட்டது — மற்றவர்கள் உங்கள் பெயர், புகைப்படம் மற்றும் சுயவிவரத்தை மட்டுமே பார்க்கிறார்கள்',
    'auth_preview_my_profile': 'எனது சுயவிவரத்தை முன்னோட்டமிடவும்',
    'auth_preview_my_profile_desc':
        'மேலே உள்ள அமைப்பின் அடிப்படையில் மற்றவர்கள் என்ன பார்க்கிறார்கள் என்பதைப் பாருங்கள்',
    'auth_share_activity_friends': 'நண்பர்களுடன் செயல்பாட்டைப் பகிரவும்',
    'auth_share_activity_friends_desc':
        'பயண செக்-இன்கள் மற்றும் விமர்சனங்கள் நண்பர்களுக்குத் தோன்றும்',
    'auth_location_sharing': 'இருப்பிடப் பகிர்வு',
    'auth_location_sharing_desc':
        'இந்தப் பயணத்தில் அருகிலுள்ள பரிந்துரைகளுக்குப் பயன்படுத்தப்படுகிறது',
    'auth_security_section': 'பாதுகாப்பு',
    'auth_two_factor_enabled_desc':
        'இயக்கப்பட்டது — உள்நுழையும்போது உங்கள் மின்னஞ்சலுக்கு ஒரு குறியீடு அனுப்பப்படும்',
    'auth_two_factor_disabled_desc':
        'உள்நுழையும்போது கூடுதல் படியாக உங்களுக்கு மின்னஞ்சல் குறியீட்டை அனுப்பவும்',
    'auth_your_data_section': 'உங்கள் தரவு',
    'auth_download_my_data': 'எனது தரவைப் பதிவிறக்கவும்',
    'auth_download_my_data_desc':
        'உங்கள் பயணங்கள் மற்றும் செயல்பாடுகளை ஏற்றுமதி செய்யவும்',
    'auth_export_not_available_demo': 'இந்த டெமோவில் ஏற்றுமதி கிடைக்கவில்லை',
    'auth_delete_account': 'கணக்கை நீக்கு',
    'auth_delete_account_confirm_title': 'உங்கள் கணக்கை நீக்கவா?',
    'auth_delete_account_confirm_body':
        'இது உங்கள் சுயவிவரம், பயணங்கள் மற்றும் செயல்பாட்டை நிரந்தரமாக அகற்றும். இதைச் செயல்தவிர்க்க முடியாது.',
    'auth_profile_now_public':
        'உங்கள் சுயவிவரம் இப்போது பொதுவானது — யாரும் உங்கள் முழு விவரங்களையும் பார்க்கலாம்',
    'auth_profile_now_private':
        'உங்கள் சுயவிவரம் இப்போது தனிப்பட்டது — மற்றவர்கள் உங்கள் பெயர், புகைப்படம் மற்றும் சுயவிவரத்தை மட்டுமே பார்க்கிறார்கள்',
    'auth_2fa_now_on': 'இரு-காரணி அங்கீகாரம் இப்போது இயக்கப்பட்டுள்ளது',
    'auth_2fa_now_off': 'இரு-காரணி அங்கீகாரம் இப்போது முடக்கப்பட்டுள்ளது',
    'auth_support_request_word': 'ஆதரவு கோரிக்கை',
    'auth_couldnt_load_conversation': 'இந்த உரையாடலை ஏற்ற முடியவில்லை.',
    'auth_no_messages_yet': 'இதுவரை செய்திகள் இல்லை.',
