    'auth_faq_q1': 'Wie erstelle ich eine neue Reise?',
    'auth_faq_a1':
        'Gehe zum Reisen-Tab und tippe auf die "+"-Schaltfläche, oder nutze "Neue Reise" aus den Schnellaktionen des Startbildschirms. Gib dein Reiseziel, Daten und Interessen ein, und lass den KI-Planer deinen Reiseplan erstellen.',
    'auth_faq_q2': 'Kann ich meinen Reiseplan nach der Erstellung bearbeiten?',
    'auth_faq_a2':
        'Ja — öffne deine Reise, tippe auf das Bearbeiten-Symbol, um Reisedetails zu aktualisieren, oder nutze "Zeitplan Bearbeiten" im Werkzeugraster, um Stopps tageweise hinzuzufügen, zu entfernen oder neu anzuordnen.',
    'auth_faq_q3': 'Wie funktioniert der Budget-Tracker?',
    'auth_faq_a3':
        'Lege ein Gesamtbudget im Budgetplaner fest und erfasse dann Ausgaben in jeder Kategorie. Ausgaben Teilen verteilt die Kosten auf deine Reisegruppe und verfolgt, wer dem Reiseorganisator etwas schuldet.',
    'auth_faq_q4': 'Funktioniert die App offline?',
    'auth_faq_a4':
